def parse_row(line: str) -> list[str]:
    fields = []
    current = []
    in_quotes = False
    i = 0
    n = len(line)
    while i < n:
        char = line[i]
        if in_quotes:
            if char == '"':
                # Check for escaped quote ("") inside quotes
                if i + 1 < n and line[i + 1] == '"':
                    current.append('"')
                    i += 2
                    continue
                else:
                    in_quotes = False
                    i += 1
                    continue
            else:
                current.append(char)
        else:
            if char == '"':
                in_quotes = True
            elif char == ',':
                fields.append(''.join(current))
                current = []
            else:
                current.append(char)
        i += 1
    # Append the final field (no trailing comma expected, but handle it anyway)
    fields.append(''.join(current))
    return fields
```

